import re

PROMPT = re.compile(r"^\(lldb\) (?P<command>\S.*?)\s*$")
EXE = re.compile(r"^Current executable set to '(?P<path>[^']*)' \((?P<arch>[^)]*)\)\.$")
BREAK = re.compile(r"^Breakpoint (?P<bid>[\d.]+): where = (?P<where>\S(?:.*?\S)?), address = (?P<address>0x[0-9a-fA-F]+)\s*$")
PROC = re.compile(r"^Process (?P<pid>\d+) (?P<event>[a-z]+)(?::? (?P<detail>\S.*?))?\s*$")
THREAD = re.compile(r"^\s*\*?\s*thread #(?P<thread>\d+), name = '(?P<name>[^']*)', stop reason = (?P<reason>\S(?:.*?\S)?)\s*$")
FRAME = re.compile(r"^\s*(?P<selected>\*)?\s*frame #(?P<frame>\d+): (?P<address>0x[0-9a-fA-F]+) (?P<module>[^`]+)`(?P<function>\S(?:.*?\S)?)(?: at (?P<location>\S+))?\s*$")
SOURCE = re.compile(r"^(?P<marker>->)?\s*(?P<lineno>\d+)\s+\t(?P<code>.*)$")
CARET = re.compile(r"^\s+\t\s*\^$")
VAR = re.compile(r"^\((?P<vtype>[^)]*)\) (?P<name>\S+) = (?P<value>.*)$")
OPEN = re.compile(r"^\((?P<vtype>[^)]*)\)(?: (?P<name>\S+) =)? \{$")
FIELD = re.compile(r"^\s+(?P<field>\w+) = (?P<value>.*)$")
FIELD_OPEN = re.compile(r"^\s+(?P<field>\w+) = \{$")
CLOSE = re.compile(r"^\s*\}$")
IMAGE = re.compile(r"^\[\s*(?P<index>\d+)\] (?P<image>\S.*?)\s*$")


def parse(lines):
    skip = []
    tables = {}
    order = ["commands", "executable", "breakpoints", "process events", "threads", "frames",
             "source", "variables", "struct fields", "images"]
    for n in order:
        tables[n] = ([], [])

    def add(name, i, rec):
        tables[name][0].append(i); tables[name][1].append(rec)

    step, command, thread, struct, path = 0, "", "", None, []
    for i, ln in enumerate(lines):
        if not ln.strip():
            continue
        m = PROMPT.match(ln)
        if m:
            step += 1; command = m.group("command"); thread = ""; struct = None; path = []
            add("commands", i, {"step": step, "command": command}); continue
        ctx = {"step": step, "command": command}
        if struct is not None:
            if CLOSE.match(ln):
                if path:
                    path.pop()
                else:
                    struct = None
                skip.append(i); continue
            m = FIELD_OPEN.match(ln)
            if m:
                path.append(m.group("field")); skip.append(i); continue
            m = FIELD.match(ln)
            if m:
                rec = dict(ctx); rec.update(struct)
                rec["field"] = ".".join(path + [m.group("field")]); rec["value"] = m.group("value")
                add("struct fields", i, rec); continue
        m = OPEN.match(ln)
        if m:
            struct = {"type": m.group("vtype"), "name": m.group("name") or ""}; path = []
            skip.append(i); continue
        m = EXE.match(ln)
        if m:
            add("executable", i, dict(ctx, path=m.group("path"), arch=m.group("arch"))); continue
        m = BREAK.match(ln)
        if m:
            add("breakpoints", i, dict(ctx, id=m.group("bid"), where=m.group("where"), address=m.group("address"))); continue
        m = PROC.match(ln)
        if m:
            add("process events", i, dict(ctx, pid=m.group("pid"), event=m.group("event"), detail=m.group("detail") or "")); continue
        m = THREAD.match(ln)
        if m:
            thread = m.group("thread")
            add("threads", i, dict(ctx, thread=thread, name=m.group("name"), stop_reason=m.group("reason"))); continue
        m = FRAME.match(ln)
        if m:
            add("frames", i, dict(ctx, thread=thread, selected=m.group("selected") or "", frame=m.group("frame"),
                                  address=m.group("address"), module=m.group("module"),
                                  function=m.group("function"), location=m.group("location") or "")); continue
        if CARET.match(ln):
            skip.append(i); continue
        m = SOURCE.match(ln)
        if m:
            add("source", i, dict(ctx, line=m.group("lineno"), current=m.group("marker") or "", code=m.group("code"))); continue
        m = VAR.match(ln)
        if m:
            add("variables", i, dict(ctx, type=m.group("vtype"), name=m.group("name"), value=m.group("value"))); continue
        m = IMAGE.match(ln)
        if m:
            add("images", i, dict(ctx, index=m.group("index"), image=m.group("image"))); continue
    blocks = [{"name": n, "kind": "table", "lines": tables[n][0], "records": tables[n][1]} for n in order if tables[n][1]]
    return {"blocks": blocks, "skip": skip}
